const projects=[{title:'A club for the curious.',description:'A digital after-dark playground where sound, identity, and a little bit of chaos meet.',tags:'EXPERIENCE / IDENTITY / SOUND',art:'AFTER<br>HOURS'},{title:'Objects with a point of view.',description:'A playful imaginary shop for everyday things that refuse to behave ordinarily.',tags:'COMMERCE / ART DIRECTION / 3D',art:'ODD<br>OBJECTS'},{title:'A different kind of wilderness.',description:'An imagined field guide to the unexpected beauty growing between nature and technology.',tags:'EDITORIAL / INTERACTION / WORLD BUILDING',art:'NEW<br>NATURE'}];
document.querySelectorAll('.project').forEach(button=>button.addEventListener('click',()=>{const n=Number(button.dataset.project),p=projects[n];document.querySelectorAll('.project').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelector('#project-number').textContent=String(n+1).padStart(2,'0');document.querySelector('#project-title').textContent=p.title;document.querySelector('#project-description').textContent=p.description;document.querySelector('#project-tags').textContent=p.tags;document.querySelector('#art-title').innerHTML=p.art+'<span>®</span>';document.querySelector('#project-art').className='project-art art-'+n}));
const canvas=document.querySelector('#sculpture'),ctx=canvas.getContext('2d');let w,h,dpr,angle=0,tilt=.45,drag=false,lastX=0,lastY=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
function point(u,v){const R=1.2+.17*Math.cos(3*u),r=.48+.12*Math.sin(5*u);let x=(R+r*Math.cos(v))*Math.cos(u),y=(R+r*Math.cos(v))*Math.sin(u),z=r*Math.sin(v)+.14*Math.sin(3*u);let a=angle,xx=x*Math.cos(a)-z*Math.sin(a),zz=x*Math.sin(a)+z*Math.cos(a);let yy=y*Math.cos(tilt)-zz*Math.sin(tilt);zz=y*Math.sin(tilt)+zz*Math.cos(tilt);const scale=Math.min(w*.21,h*.30),perspective=4.5/(4.5+zz);return{x:w*.51+xx*scale*perspective,y:h*.5+yy*scale*perspective,z:zz}}
function draw(){ctx.clearRect(0,0,w,h);const quads=[],nu=52,nv=20;for(let i=0;i<nu;i++)for(let j=0;j<nv;j++){let u=i*Math.PI*2/nu,v=j*Math.PI*2/nv,du=Math.PI*2/nu,dv=Math.PI*2/nv;let p=[point(u,v),point(u+du,v),point(u+du,v+dv),point(u,v+dv)];quads.push({p,z:p.reduce((s,q)=>s+q.z,0)/4,i,j})}quads.sort((a,b)=>b.z-a.z);for(const q of quads){let light=Math.max(0,Math.min(1,(q.z+2)/4)),r=Math.round(255-65*light),g=Math.round(122-55*light),b=Math.round(171+55*light);ctx.beginPath();ctx.moveTo(q.p[0].x,q.p[0].y);q.p.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.closePath();ctx.fillStyle=`rgb(${r},${g},${b})`;ctx.fill();ctx.strokeStyle='rgba(48,22,46,.35)';ctx.lineWidth=.65;ctx.stroke()}if(!drag&&!reduced)angle+=.006;requestAnimationFrame(draw)}
canvas.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag){angle+=(e.clientX-lastX)*.012;tilt+=(e.clientY-lastY)*.008;lastX=e.clientX;lastY=e.clientY}});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('pointercancel',()=>drag=false);window.addEventListener('resize',resize);resize();draw();
